using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — shows required fixes for EF Core 9 Cosmos provider.
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: EF Core 9 renamed default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so explicitly configure the old name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: EF Core 9 no longer embeds the discriminator in the JSON id property.
        // Existing documents have id = "Session|<key>". Preserve that format.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// Fix 3: EF Core 9 Cosmos provider no longer supports synchronous I/O.
// All sync calls (ToList, SaveChanges, etc.) now throw.
// Convert to async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.SaveChanges();

    // AFTER — use async equivalents:
    public async Task<List<Session>> GetSessionsAsync(string name)
    {
        return await _db.Sessions.Where(s => s.Name == name).ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

